#!/bin/bash
# Download all data and models needed for this environment.
#
# Run on a node with internet access BEFORE building the container
# or submitting compute jobs.
#
# This script should be idempotent — safe to run multiple times.
# It should skip files that already exist.
#
# Update the storage estimate below as you add downloads.
#
# Estimated total download size: 0 GB for the lightweight benchmark.
# Estimated disk usage after extraction: <1 MB.
#
# This benchmark has no external downloads. The small procedural dataset is
# generated by the run scripts after dependencies are installed.

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
cd "$REPO_ROOT"

if python -c "import numpy" >/dev/null 2>&1; then
  python data/articulated_gaussians.py
else
  echo "No external downloads required; synthetic data will be generated by the run scripts."
fi
